import{_ as d,o as e,c as o,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const b=JSON.parse('{"title":"语音聊天链路","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/voice.md","filePath":"advanced/voice.md","lastUpdated":1791088295000}'),c={name:"advanced/voice.md"};function r(i,t,s,p,n,l){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="语音聊天链路" tabindex="-1">语音聊天链路 <a class="header-anchor" href="#语音聊天链路" aria-label="Permalink to &quot;语音聊天链路&quot;">​</a></h1><p>语音聊天不承担播放同步的职责，因此它不经过 Socket.IO，而是走一条独立的实时音频链路。本页说明这条链路的构成：谁处理音频、连接怎么建立、管理动作如何生效，以及部署时哪些环节会退化。功能层面的说明见<a href="/basic/features">功能说明</a>，端口映射与变量清单见<a href="/basic/install">安装与部署</a>与<a href="/advanced/env">环境变量</a>。</p><h2 id="音频由独立服务承载" tabindex="-1">音频由独立服务承载 <a class="header-anchor" href="#音频由独立服务承载" aria-label="Permalink to &quot;音频由独立服务承载&quot;">​</a></h2><p>实时音频交给 LiveKit 处理。LiveKit 是开源的 WebRTC 实时通信服务，媒体形态为 SFU（Selective Forwarding Unit，选择性转发单元）：每个客户端把自己的音频上传一份，服务端只做转发不做混流，因此上行带宽随人数线性增长而不会互相干扰。</p><p>主后端不参与音频流转，只负责三件事：签发接入凭证、执行禁言与踢出、代理信令。整体拓扑如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 ── POST /api/voice/token ──▶ 后端（3333）── 签发 AccessToken</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├─ 信令 wss://页面域名/rtc ──▶ 后端 /rtc 反代 ──▶ livekit-server（3336）</span></span>
<span class="line"><span>   └─ 媒体 RTP over UDP 3333 ──────────────▶ livekit-server</span></span>
<span class="line"><span>                  （UDP 被拦截时：ICE/TCP 3337 直连，或 TURN/TLS 5349 中继）</span></span></code></pre></div><p>各端口的职责如下表。</p><table tabindex="0"><thead><tr><th>端口</th><th>协议</th><th>用途</th></tr></thead><tbody><tr><td>3333</td><td>TCP</td><td>页面、REST API、Socket.IO，以及 <code>/rtc</code> 信令反代</td></tr><tr><td>3333</td><td>UDP</td><td>语音媒体（RTP），与页面同号不同协议</td></tr><tr><td>3337</td><td>TCP</td><td>ICE/TCP 媒体直连，管理端把语音传输模式切到 TCP 时启用（按需）</td></tr><tr><td>3336</td><td>TCP</td><td>livekit-server 的 HTTP 与信令端口，仅内部使用</td></tr><tr><td>5349</td><td>TCP</td><td>TURN/TLS 中继，UDP 被拦截时的兜底通道，需显式配置</td></tr></tbody></table><p>livekit-server 是独立的 Go 二进制，无法嵌入 pkg 打包出的单文件产物，因此以伴生进程的形式随主进程启停：单文件版由 <code>build-all.js</code> 把二进制分发到可执行文件旁边，容器版内嵌在镜像里。开发模式下若二进制缺失，程序会自动从 GitHub Releases 下载到 <code>backend/dev-bin/</code>。</p><h2 id="接入凭证" tabindex="-1">接入凭证 <a class="header-anchor" href="#接入凭证" aria-label="Permalink to &quot;接入凭证&quot;">​</a></h2><p>浏览器加入语音前先向后端换一个令牌，这个令牌是客户端连接 LiveKit 的唯一凭证。接口为 <code>POST /api/voice/token</code>，请求体带 <code>roomId</code> 与 <code>username</code>，需要登录态。</p><p>服务端把 ZViewer 房间映射为 LiveKit 房间，房间名固定为 <code>voice:&lt;roomId&gt;</code> 前缀，不同 ZViewer 房间之间彼此隔离。签发的令牌声明一份 grant（授权范围），授予接入、发布、订阅与数据通道四项权限。</p><p>参与者的身份（identity）按登录态分两种规则，重连时的行为不同。</p><table tabindex="0"><thead><tr><th>身份</th><th>生成规则</th><th>重连行为</th></tr></thead><tbody><tr><td>登录用户</td><td><code>user:&lt;userId&gt;</code></td><td>身份稳定，重连后顶替自己上一条麦克风轨</td></tr><tr><td>游客</td><td><code>guest:&lt;时间戳36进制&gt;&lt;4位随机&gt;</code></td><td>每次加入都是新身份，不顶替他人</td></tr></tbody></table><p>游客身份不落库，因此同一游客反复进出房间会在 LiveKit 侧留下多条记录，直到房间销毁。令牌本身由 <code>LIVEKIT_API_KEY</code> 与 <code>LIVEKIT_API_SECRET</code> 签名，未配置这两个变量时接口返回 503，前端提示语音未就绪。</p><p><strong>客户端地址按请求头推导</strong>，不写在服务端配置里。优先取 <code>LIVEKIT_URL</code>；未配置时从 <code>x-forwarded-host</code> / <code>x-forwarded-proto</code> 或 <code>Host</code> 头推导协议与域名，HTTPS 页面自动得到 <code>wss://</code>，反代与 CDN 场景因此无需额外配置。这样做是为了避开在容器或多网卡环境探测本机 IP——探测结果通常是 Docker bridge 网段（<code>172.24.x.x</code>），浏览器根本不可达。</p><blockquote><p>一个容易踩的坑：新版 SDK 的 <code>token.toJwt()</code> 返回 Promise，必须 <code>await</code>。直接取同步值会序列化成 <code>[object Object]</code>，LiveKit 侧一律返回 401。</p></blockquote><h2 id="采集与发布" tabindex="-1">采集与发布 <a class="header-anchor" href="#采集与发布" aria-label="Permalink to &quot;采集与发布&quot;">​</a></h2><p>麦克风采集使用 <code>getUserMedia</code>，开启回声消除、降噪与自动增益，并强制单声道。这三项处理由浏览器完成，不占用服务器算力。</p><p>采集到的音频流进入一条 48kHz 的 <code>AudioContext</code> 节点链，<code>micGain</code> 负责输入音量，之后分流到三个终点。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>麦克风 ──▶ micGain ──┬──▶ produceDest ──▶ 发布轨（送往 LiveKit）</span></span>
<span class="line"><span>                     ├──▶ monitorGain ──▶ ctx.destination（耳机反送）</span></span>
<span class="line"><span>                     └──▶ analyser（电平可视化）</span></span></code></pre></div><p>音频上下文<strong>不强制指定采样率</strong>。声卡硬件速率不尽相同（蓝牙 HFP 常见 44.1kHz），强行重采样到 48kHz 会形成采集与上下文两级的双重转换，反送与发布会出现周期性卡顿。LiveKit 对采集速率没有要求，用硬件默认值即可。</p><p>发布时指定编码档位，参数直接决定听感。</p><table tabindex="0"><thead><tr><th>参数</th><th>取值</th><th>原因</th></tr></thead><tbody><tr><td><code>audioPreset</code></td><td><code>music</code></td><td>SDK 默认按语音会议档编码（约 24~32kbps），听感发闷；<code>music</code> 档为 48kbps 全带宽 Opus</td></tr><tr><td><code>dtx</code></td><td><code>false</code></td><td>关闭静默段 discontinuous transmission，避免静音段落切换时的音质劣化</td></tr><tr><td><code>red</code></td><td><code>true</code></td><td>保留 RED 冗余编码抵抗丢包</td></tr></tbody></table><p><strong>自闭麦</strong>（本地静音）只需把发布轨的 <code>enabled</code> 置为 false，不发任何服务端请求。管理员禁言则是另一套机制，见「禁言与踢出」一节。</p><h2 id="收听与成员状态" tabindex="-1">收听与成员状态 <a class="header-anchor" href="#收听与成员状态" aria-label="Permalink to &quot;收听与成员状态&quot;">​</a></h2><p>远端音频轨不直接出声，而是为每个成员创建一个隐藏的 <code>&lt;audio&gt;</code> 元素承载。成员列表在参与者连接、断开、metadata 变更时刷新；每个成员还挂一个 <code>AnalyserNode</code>（<code>fftSize</code> 为 256、平滑系数 0.6）仅用于电平可视化，不参与发声。</p><p>音量分两层：全局音量乘以单成员音量，两者相乘后写入该成员的 <code>&lt;audio&gt;.volume</code>。</p><p>反送（自己听见自己）按浏览器分别处理。Chrome 走媒体元素路径；Firefox 播放实时 <code>MediaStream</code> 有缓冲积压缺陷会卡顿，改走 <code>AudioContext</code> 直连输出。反送默认关闭。</p><h2 id="禁言与踢出" tabindex="-1">禁言与踢出 <a class="header-anchor" href="#禁言与踢出" aria-label="Permalink to &quot;禁言与踢出&quot;">​</a></h2><p>管理动作通过 REST 接口执行，权限在服务端校验。禁言采用双通道强制，客户端无法绕过。</p><ol><li><strong>服务器侧静音</strong>：服务端调用 <code>mutePublishedTrack</code> 把目标成员已发布的所有音频轨静音。这是服务端操作，与客户端状态无关。</li><li><strong>metadata 标记</strong>：服务端把参与者 metadata 写为 <code>{&quot;adminMuted&quot;: true}</code>。成员列表据此渲染 UI，被禁言者的客户端收到 <code>ParticipantMetadataChanged</code> 事件后锁定麦克风并提示，解禁时自动恢复。</li></ol><p>禁言期间该成员无法自行开麦。踢出则直接调用 <code>removeParticipant</code>，被踢者的客户端收到 <code>Disconnected</code> 事件后复位界面。</p><p>三处权限判定的口径与房间管理一致：root、本人为主房主的 admin、房主、房管（<code>Room.moderators</code> 数组中包含该用户）。</p><table tabindex="0"><thead><tr><th>接口</th><th>动作</th><th>权限</th></tr></thead><tbody><tr><td><code>POST /api/voice/token</code></td><td>签发接入凭证</td><td>登录</td></tr><tr><td><code>POST /api/voice/mute</code></td><td>禁言 / 解禁对方麦克风</td><td>root / 房主 / 房管</td></tr><tr><td><code>POST /api/voice/kick</code></td><td>踢出语音</td><td>root / 房主 / 房管</td></tr></tbody></table><h2 id="信令反代" tabindex="-1">信令反代 <a class="header-anchor" href="#信令反代" aria-label="Permalink to &quot;信令反代&quot;">​</a></h2><p>LiveKit 的信令走两条通道，主后端都要代理，否则浏览器连不上。</p><ul><li><strong>HTTP 通道</strong>：客户端连接前先发 <code>GET /rtc/v1/validate</code> 校验令牌，这是普通 HTTP 请求。HTTPS 页面下若不经代理，混合内容策略会直接拦截。</li><li><strong>WebSocket 通道</strong>：后续信令帧通过 <code>/rtc</code> 的 HTTP Upgrade 升级为 WebSocket。升级后的帧是不透明字节流，主后端只做裸 TCP 双向管道，不解析协议。</li></ul><p><code>upgrade</code> 事件处理器只放行两类路径：以 <code>/socket.io</code> 开头的交给 Socket.IO 自行处理，以 <code>/rtc</code> 开头的隧道到 livekit-server，其余连接一律销毁。上游地址每次升级时从 <code>LIVEKIT_API_HOST</code> 解析（裸机为 <code>127.0.0.1:3336</code>，compose 部署为 <code>livekit:3336</code>），以兼容运行时注入的环境变量。</p><h2 id="内嵌服务的启动与降级" tabindex="-1">内嵌服务的启动与降级 <a class="header-anchor" href="#内嵌服务的启动与降级" aria-label="Permalink to &quot;内嵌服务的启动与降级&quot;">​</a></h2><p>启动流程在数据库初始化之后触发：先从系统设置读取语音传输模式（udp/tcp），再以 fire-and-forget 方式拉起子进程，不阻塞主服务。下载二进制期间 <code>/api/voice/token</code> 返回 503，前端提示语音未就绪。</p><p>livekit-server 的启动参数如下（UDP 模式，默认）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>livekit-server --dev --bind :: --port 3336 --udp-port 3333 --keys &quot;&lt;key&gt;: &lt;secret&gt;&quot;</span></span></code></pre></div><p>管理端把语音传输模式切换为 TCP 时，参数追加 <code>--tcp-port 3337</code>（详见「语音传输模式」一节）。</p><p><code>--bind ::</code> 以双栈监听，同时收 IPv4 与 IPv6（IPv4 连接以 v4-mapped 形式进入）。绑定 <code>0.0.0.0</code> 只会收到 IPv4，公网 IPv6 用户的媒体流将无法建立。若所在环境没有 IPv6 协议栈导致绑定 <code>::</code> 失败，程序自动回退 <code>0.0.0.0</code> 重试一次，代价是 IPv6 媒体不可用但语音整体可用。</p><p><code>--keys</code> 的格式要求冒号后必须带一个空格，缺空格时 livekit-server 会直接退出。启动后轮询 3336 端口等待就绪，超时 15s 判定失败。</p><p>程序为子进程注册 <code>exit</code>、<code>SIGINT</code>、<code>SIGTERM</code> 三个钩子，主进程退出时一并终止。</p><p>各项配置的缺省值如下表，显式配置优先于缺省值。</p><table tabindex="0"><thead><tr><th>变量</th><th>缺省值</th><th>作用</th></tr></thead><tbody><tr><td><code>LIVEKIT_API_KEY</code></td><td><code>devkey</code></td><td>令牌签名密钥</td></tr><tr><td><code>LIVEKIT_API_SECRET</code></td><td><code>zviewer-dev-secret</code></td><td>令牌签名密钥</td></tr><tr><td><code>LIVEKIT_API_HOST</code></td><td><code>http://127.0.0.1:3336</code></td><td>服务端 API 与信令反代的上游地址</td></tr><tr><td><code>LIVEKIT_BIND</code></td><td><code>::</code></td><td>内嵌服务监听地址</td></tr><tr><td><code>LIVEKIT_RTC_TCP_PORT</code></td><td><code>3337</code></td><td>ICE/TCP 端口（语音传输模式为 TCP 时开启）</td></tr><tr><td><code>LIVEKIT_EXTERNAL</code></td><td>未设置</td><td>设为 <code>1</code> 时跳过内嵌服务，改用外置 LiveKit</td></tr></tbody></table><p>生产包（pkg 单文件）不会联网下载二进制。找不到伴生二进制时只打印告警并给出重建指引，语音功能随之不可用。</p><h2 id="语音传输模式-udp-tcp" tabindex="-1">语音传输模式（UDP / TCP） <a class="header-anchor" href="#语音传输模式-udp-tcp" aria-label="Permalink to &quot;语音传输模式（UDP / TCP）&quot;">​</a></h2><p>管理端「基础设置 → 语音传输模式」控制语音媒体的通道构成，保存后后端自动热重启 livekit-server 子进程，进行中的语音会短暂中断并自动重连。</p><table tabindex="0"><thead><tr><th>模式</th><th>livekit-server 启动参数</th><th>部署侧要求</th></tr></thead><tbody><tr><td>UDP（默认）</td><td><code>--udp-port 3333</code></td><td>放行 3333/udp</td></tr><tr><td>TCP</td><td><code>--udp-port 3333</code> + <code>--tcp-port 3337</code></td><td>额外放行 3337/tcp（Docker 需补端口映射）</td></tr></tbody></table><p>TCP 模式开启 LiveKit 原生 ICE/TCP 直连：服务器同时广播 UDP 与 TCP 两路候选，由浏览器 ICE 自动选路——UDP 可用时走低延迟直连，被运营商或企业防火墙拦截时自动经 3337/tcp 连接媒体。UDP 通道始终开启（LiveKit 不支持禁用 UDP 候选），因此 TCP 模式是「加开兜底」而非「替换」；端口号可用环境变量 <code>LIVEKIT_RTC_TCP_PORT</code> 覆盖。</p><p>TCP 直连与 TURN/TLS 中继解决的是同一类问题（UDP 被拦截），机制不同：</p><table tabindex="0"><thead><tr><th></th><th>ICE/TCP 3337</th><th>TURN/TLS 5349</th></tr></thead><tbody><tr><td>连接形态</td><td>浏览器与服务器<strong>直连</strong></td><td>经 TURN 服务器<strong>中继</strong></td></tr><tr><td>部署要求</td><td>无需域名与证书</td><td>需域名与正式证书（自签不被 WebRTC 信任）</td></tr><tr><td>启用方式</td><td>管理端设置即时切换</td><td>配置 <code>LIVEKIT_TURN_DOMAIN</code> / <code>CERT</code> / <code>KEY</code> 三项</td></tr><tr><td>穿透能力</td><td>受限于网络是否放行 3337/tcp</td><td>更强（TLS 流量伪装为普通 HTTPS）</td></tr></tbody></table><p>二者可以同时部署，客户端按连通性自动选择。</p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><p>下表按现象列出常见原因与处理方式。</p><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>前端提示语音未就绪</td><td>内嵌服务仍在下载或启动，或 <code>LIVEKIT_API_KEY</code> / <code>LIVEKIT_API_SECRET</code> 未注入</td><td>查看服务端日志的 <code>[voice]</code> 段；单文件版确认包内含 <code>livekit-server</code></td></tr><tr><td>接入后听不到别人声音</td><td>3333/udp 未放行，媒体无法直连</td><td>放行 UDP 3333；运营商或企业防火墙拦 UDP 时，改用 TCP 传输模式（3337/tcp）或配置 TURN/TLS 三项</td></tr><tr><td>页面在 HTTPS 下报混合内容</td><td><code>/rtc</code> 信令未反代</td><td>确认反代把 <code>/rtc</code> 转发到主端口 3333</td></tr><tr><td>连接后立刻被断开</td><td>令牌序列化错误</td><td>检查是否 <code>await</code> 了 <code>token.toJwt()</code></td></tr><tr><td>只有 IPv6 用户连不上</td><td>监听地址绑到了 <code>0.0.0.0</code></td><td>确认 <code>LIVEKIT_BIND</code> 保持 <code>::</code></td></tr><tr><td>管理员禁言无效</td><td>目标已不在语音房间</td><td>禁言接口在参与者列表中找不到目标时返回 404</td></tr></tbody></table><h2 id="常量速查" tabindex="-1">常量速查 <a class="header-anchor" href="#常量速查" aria-label="Permalink to &quot;常量速查&quot;">​</a></h2><p>下表汇总本页涉及的固定取值。</p><table tabindex="0"><thead><tr><th>常量</th><th>值</th></tr></thead><tbody><tr><td>LiveKit 版本（开发模式自动下载）</td><td>v1.13.7</td></tr><tr><td>信令 / 媒体端口</td><td>3336 / 3333</td></tr><tr><td>ICE/TCP 端口（TCP 模式）</td><td>3337</td></tr><tr><td>TURN/TLS 端口</td><td>5349</td></tr><tr><td>就绪等待超时</td><td>15s</td></tr><tr><td>发布编码档</td><td><code>music</code>（48kbps Opus），<code>dtx: false</code>，<code>red: true</code></td></tr><tr><td>电平分析 fftSize / 平滑系数</td><td>256 / 0.6</td></tr></tbody></table>`,63)])])}const T=d(c,[["render",r]]);export{b as __pageData,T as default};
